$s=db()->prepare("SELECT a.*,u.full_name,u.email,u.username FROM attempts a JOIN users u ON u.id=a.user_id WHERE a.exam_id=? ORDER BY a.id DESC");$s->execute([$id]);$rows=$s->fetchAll();
$detail=null;$answers=[];
if($attemptId){$d=db()->prepare("SELECT a.*,u.full_name,u.email,e.title FROM attempts a JOIN users u ON u.id=a.user_id JOIN exams e ON e.id=a.exam_id WHERE a.id=? AND a.exam_id=?");$d->execute([$attemptId,$id]);$detail=$d->fetch();if($detail){$q=db()->prepare("SELECT q.id,q.type,q.question_text,q.points,q.use_answer_key,q.correct_option,q.matrix_correct_mirip,q.matrix_correct_tidak,q.essay_answer_key,a.selected_option,a.matrix_answer,a.essay_answer,a.essay_score FROM questions q LEFT JOIN answers a ON a.question_id=q.id AND a.attempt_id=? WHERE q.exam_id=? ORDER BY q.sort_order,q.id");$q->execute([$attemptId,$id]);$answers=$q->fetchAll();}}
