<?php if($detail):?><section class="attempt-detail"><div class="detail-header"><div><h3>Attempt #<?=h($detail['id'])?> — <?=h($detail['full_name'])?></h3><p><?=h($detail['email']??$detail['username'])?> · Mulai <?=h($detail['started_at'])?> · Selesai <?=h($detail['submitted_at']?:'—')?> · Nilai <b><?=h($detail['score'])?></b></p></div><a class="ui-btn secondary" href="results.php?id=<?=$id?>">Tutup Detail</a></div><?php foreach($answers as $i=>$a):?><article class="ui-card attempt-question <?= $a['type']==='essay'?'essay-card':''?>"><div class="question-card-head"><div class="question-number"><?=($i+1)?></div><div class="question-meta"><span class="type-pill <?=$a['type']==='essay'?'essay':''?>"><?=h($a['type']==='essay'?'Essay':($a['type']==='matrix_disc'?'Matriks / DISC':'Pilihan Ganda'))?></span><span><?=h($a['points'])?> poin</span></div></div><div class="question-text"><?=nl2br(h($a['question_text']))?></div><?php if($a['type']==='essay'):?><div class="answer-panel"><b>Jawaban peserta</b><div><?=nl2br(h($a['essay_answer']??'Belum dijawab'))?></div></div><?php if($a['essay_answer_key']):?><div class="key-panel"><b>Jawaban acuan</b><div><?=nl2br(h($a['essay_answer_key']))?></div></div><?php endif;?><?php $gradingEnabled=(int)($a['use_answer_key']??0)===1 && (float)$a['points']>0;$graded=$a['essay_score']!==null;?><?php if($gradingEnabled):?><form method="post" action="save_essay_grade.php" class="grade-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="attempt_id" value="<?=$attemptId?>"><input type="hidden" name="question_id" value="<?=$a['id']?>"><label>Nilai (maks. <?=h($a['points'])?>)</label><input type="number" step="0.5" min="0" max="<?=h($a['points'])?>" name="essay_score" value="<?=$graded?h($a['essay_score']):''?>" placeholder="Belum dinilai"><button class="ui-btn">Simpan Nilai</button></form><?php else:?><div class="answer-panel"><b>Penilaian</b><div>Penilaian dengan kunci &amp; poin tidak aktif untuk soal ini.</div></div><?php endif;?><?php elseif($a['type']==='matrix_disc'):?><?php $ma=json_decode((string)($a['matrix_answer']??''),true)?:[];?><div class="answer-compare"><span>MIRIP peserta: <b><?=h($ma['mirip']??'Belum dijawab')?></b></span><span>TIDAK MIRIP peserta: <b><?=h($ma['tidak_mirip']??'Belum dijawab')?></b></span></div><?php else:?><div class="answer-compare"><span>Jawaban peserta: <b><?=h($a['selected_option']??'Belum dijawab')?></b></span><?php if(!empty($a['correct_option'])):?><span>Kunci: <b><?=h($a['correct_option'])?></b></span><?php endif;?></div><?php endif;?></article><?php endforeach;?></section><?php endif;?></div><footer class="admin-footer"><span>© <?=date('Y')?> Ujian Online</span><span>Versi <?=h(app_version())?></span></footer></main></div><script>document.querySelector('.menu-toggle').onclick=()=>document.body.classList.toggle('sidebar-open');document.getElementById('attemptSearch').oninput=function(){let q=this.value.toLowerCase();document.querySelectorAll('tbody tr[data-search]').forEach(r=>r.style.display=r.dataset.search.includes(q)?'':'none')}</script></body></html>